static int exempt(const char *name)
{
    int i;
    for (i = 0; NOT_IN_C[i][0]; i++) if (!strcmp(NOT_IN_C[i][0], name)) return 1;
    return 0;
}

#define MAXV 512
static char line[1 << 16];

int main(int argc, char **argv)
{
    const char *path = argc > 1 ? argv[1] : "tests/pcode_vectors.txt";
    FILE *fp = fopen(path, "r");
    int j, fails = 0, values = 0, exact = 0, fns = 0, calls = 0;
    char prev[128] = "";
    double worst = 0, x[MAXV], y[MAXV];
    out_t o;
    if (!fp) { printf("FAIL cannot read %s (tools/pcode.py gen writes it)\n", path); return 1; }
    while (fgets(line, sizeof line, fp)) {
        char name[128], *p = line, *end;
        int ex, set, nx, ny, r, k;
        if (line[0] == '#' || line[0] == '\n') continue;
        if (sscanf(p, "%127s %d %d %d %d%n", name, &ex, &set, &nx, &ny, &k) != 5 || nx > MAXV || ny > MAXV) { printf("FAIL %s: a line that does not read\n", path); fails++; continue; }
        p += k;
        for (j = 0; j < nx + ny; j++) {
            unsigned long long w = strtoull(p, &end, 16);
            double d;
            memcpy(&d, &w, sizeof d);
            if (j < nx) x[j] = d; else y[j - nx] = d;
            p = end;
        }
        (void)set;
        calls++;
        if (strcmp(name, prev)) { fns++; strcpy(prev, name); }
        if (exempt(name)) continue;
        r = call(name, x, nx, &o);
        if (r == 0) { printf("FAIL %s: no C adapter and no stated reason\n", name); fails++; continue; }
        if (r < 0 || o.n != ny) { if (r > 0) printf("FAIL %s: %d outputs, the pseudocode %d\n", name, o.n, ny); fails++; continue; }
        for (j = 0; j < ny; j++) {
            double g = o.y[j], w = y[j], err = fabs(g - w)/(fabs(w) > 1e-300 ? fabs(w) : 1e-300);
            int same = memcmp(&g, &w, sizeof g) == 0 || (g == 0 && w == 0);
            values++;
            if (same) exact++; else if (err > worst) worst = err;
            if (!same && (ex || !(err < 1e-12))) {
                printf("FAIL %s output %d: C %.17g, pseudocode %.17g%s\n", name, j, g, w, ex ? " (no transcendental: must agree bit for bit)" : "");
                fails++;
            }
        }
    }
    fclose(fp);
    printf("pcode: %d functions, %d calls, %d values, %d bit for bit, worst relative difference %.1e; %d failure(s)\n", fns, calls, values, exact, worst, fails);
    return fails || !calls ? 1 : 0;
}
